# ruff: noqa: E501 — idea copy reads best one idea per line
"""«Свидание недели»: one idea a week on «Сегодня», taking turns — a talk, a game, romance and, only when both of you
switched it on and only from what you BOTH said «да» to in «Близость», an 18+ idea. Plain rules, no model: talks lean on
the report's weakest spheres, both high on openness → more novelty. Phrasing stays non-explicit on purpose: the card
can be seen over a shoulder, and the 18+ one opens only on a tap.
"""

import hashlib

THEMES = {"talk": "Разговор", "play": "Игра", "romance": "Романтика", "close": "Близость 18+"}
OPEN = 60  # Big Five openness (0–100) both partners need for «more novelty»


def _i(title: str, text: str, *steps: str, spheres: tuple[str, ...] = (), new: bool = False) -> dict:
    return {"title": title, "text": text, "steps": list(steps), "spheres": spheres, "new": new}


