def week_no(today) -> int:
    """Weeks since 1 January of year 1 (a Monday), so the idea changes on Mondays."""
    return (today.toordinal() - 1) // 7


def pick(week: int, seed: str, weak: list[str], open_both: bool, mutual: list[str], close_on: bool) -> dict:
    """The idea for `week`. weak: the report's weakest sphere keys; mutual: «Близость» keys both said «да» to;
    close_on: both partners switched 18+ ideas on. Each theme walks its own pool, so ideas don't repeat until it's done."""
    close = [k for k in mutual if k in CLOSE] if close_on else []
    cycle = ["talk", "play", "romance"] + (["close"] if close else [])
    theme = cycle[week % len(cycle)]
    if theme == "close":
        pool = [CLOSE[k] for k in close]
    elif theme == "talk":
        pool = [i for i in IDEAS["talk"] if set(i["spheres"]) & set(weak)] + IDEAS["talk"]  # weak spheres come round twice as often
    else:
        pool = ([i for i in IDEAS[theme] if i["new"]] if open_both else []) + IDEAS[theme]  # open to new → novelty twice as often
    offset = int(hashlib.sha256(f"{seed}:{theme}".encode()).hexdigest(), 16)
    return {"theme": theme, "theme_title": THEMES[theme], **pool[(week // len(cycle) + offset) % len(pool)]}


if __name__ == "__main__":
    from apps.compatibility.intimacy import TITLES

    assert set(CLOSE) == set(TITLES)  # every «Близость» wish has its idea, nothing more
    off = [pick(w, "pair", ["money"], False, ["hug", "trip"], close_on=False) for w in range(40)]
    assert "close" not in {i["theme"] for i in off}  # off until both switch it on
    on = [pick(w, "pair", ["money"], False, ["hug", "trip"], close_on=True) for w in range(40)]
    close = [i["title"] for i in on if i["theme"] == "close"]
    assert len(close) == 10 and set(close) == {CLOSE["hug"]["title"], CLOSE["trip"]["title"]}  # only what both said «да» to
    assert "close" not in {pick(w, "p", [], False, [], True)["theme"] for w in range(8)}  # nothing mutual → nothing 18+
    talks = [i["title"] for i in on if i["theme"] == "talk"]
    assert "Карта ваших денег" in talks and len(set(talks)) >= 8  # leans on money, still varied
    plays = [p for w in range(300) if (p := pick(w, "p", [], True, [], False))["theme"] == "play"]
    assert sum(p["new"] for p in plays) > len(plays) / 2  # both open → mostly novelty
    assert pick(5, "x", [], False, [], False) == pick(5, "x", [], False, [], False)  # same week, same idea for both
    print("ok")
